(()=>{
const host=document.querySelector('#steam-collection'),cards=[...host.querySelectorAll('a')];
const groups=['Racing','RPG','Racing','Action','Strategy','RPG','Sports','RPG','Simulation','Simulation','Action','Simulation','RPG','Strategy','Action','Shooter','Party','Simulation','Action','Shooter','Action','Strategy','Shooter','Racing','Action','Shooter','Shooter','Fighting','Shooter','Shooter','Shooter','Shooter','Fighting','Shooter','Strategy','Simulation','Shooter','Party','Simulation','Simulation','Action','RPG','Racing','Strategy','Sports','Party','Racing'];
const controls=document.createElement('div');controls.className='library-controls game-controls';controls.innerHTML='<label for="game-search">Find a game</label><input id="game-search" type="search" placeholder="Search the collection"><select id="game-category" aria-label="Game genre"></select><p role="status"></p>';host.before(controls);const select=controls.querySelector('select');for(const genre of ['All genres',...new Set(groups)].sort((a,b)=>a==='All genres'?-1:b==='All genres'?1:a.localeCompare(b))){const o=document.createElement('option');o.textContent=genre;select.append(o);}function render(){let n=0;const q=controls.querySelector('input').value.trim().toLowerCase();cards.forEach((c,i)=>{c.hidden=!(c.querySelector('h2').textContent.toLowerCase().includes(q)&&(select.value==='All genres'||groups[i]===select.value));if(!c.hidden)n++;});controls.querySelector('p').textContent=n?`${n} of ${cards.length} games`:'No matching games. Try another title or genre.';}controls.addEventListener('input',render);controls.addEventListener('change',render);render();
const launcher=document.querySelector('.byte-context-launch'),toggle=document.createElement('button');toggle.className='byte-collapse';toggle.type='button';launcher.after(toggle);let collapsed=false;try{collapsed=localStorage.getItem('byte-collapsed')==='true';}catch{}function update(){launcher.classList.toggle('is-collapsed',collapsed);toggle.textContent=collapsed?'+':'−';toggle.setAttribute('aria-label',collapsed?'Expand Byte chat button':'Minimise Byte chat button');toggle.setAttribute('aria-expanded',String(!collapsed));}toggle.onclick=()=>{collapsed=!collapsed;try{localStorage.setItem('byte-collapsed',String(collapsed));}catch{}update();};update();new MutationObserver(()=>toggle.hidden=launcher.hidden).observe(launcher,{attributes:true,attributeFilter:['hidden']});
const speed=document.createElement('button');speed.type='button';speed.className='transition-speed';document.querySelector('.chapter-controls').append(speed);let quick=false;try{quick=localStorage.getItem('transition-speed')==='quick';}catch{}function apply(){document.documentElement.dataset.transitionSpeed=quick?'quick':'cinematic';speed.textContent='Transitions: '+(quick?'quick':'cinematic');speed.setAttribute('aria-pressed',String(quick));}speed.onclick=()=>{quick=!quick;try{localStorage.setItem('transition-speed',quick?'quick':'cinematic');}catch{}apply();};apply();
})();
